import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth } from './helpers';

test.describe(`sales rep: move a lead from one stage to the next`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a rep moves a lead to a different stage, all team members see the lead in its new stage within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();

    try {
      await loginViaHash(pageA, 0);
      await loginViaHash(pageB, 1);

      // Sales rep (node 0) adds a lead so there is something to move
      await pageA.getByRole('button', { name: '+ Add Lead' }).click();
      await expect(pageA.getByText('Add Lead')).toBeVisible({ timeout: 5_000 });
      await pageA.getByLabel('Lead / Contact Name').fill('E2E Move Lead');
      await pageA.getByLabel('Company').fill('Move Corp');
      await pageA.getByLabel('Estimated Deal Value ($)').fill('15000');
      await pageA.getByRole('button', { name: 'Add Lead' }).click();
      await expect(pageA.getByText('E2E Move Lead')).toBeVisible({ timeout: 5_000 });

      // Click the lead card to open the action menu
      await pageA.getByText('E2E Move Lead').click();

      // Click the first available "Move to stage" option (→ <stage name>)
      // The action menu lists every other stage prefixed with "→ "
      await pageA.getByRole('button', { name: /^→ / }).first().click();

      // Node 0 still shows the lead (now in its new stage column)
      await expect(pageA.getByText('E2E Move Lead')).toBeVisible({ timeout: 5_000 });

      // All team members (node 1) see the lead in its new stage within 5 s
      await expect(pageB.getByText('E2E Move Lead')).toBeVisible({ timeout: 5_000 });
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });
});
